// pybytes.mjs
// Python-flavored byte helpers: UTF-8 encoding and exact CPython `bytes` repr.
//
// No dependencies; uses the global TextEncoder available in Node.js >= 11.

const encoder = new TextEncoder();

/**
 * Encode a string to a Uint8Array of UTF-8 bytes, like Python's str.encode('utf-8').
 * @param {string} str
 * @returns {Uint8Array}
 */
export function encodeUtf8(str) {
  return encoder.encode(str);
}

/**
 * Format a Uint8Array exactly like CPython's repr() of a bytes object.
 *
 * Rules (matching CPython Objects/bytesobject.c bytes_repr):
 * - Prefix 'b'.
 * - Quote selection: single quote by default; double quote only when the
 *   data contains a single quote and no double quote.
 * - '\\', '\t' (0x09), '\n' (0x0a), '\r' (0x0d) get backslash escapes.
 * - The active quote character is backslash-escaped.
 * - Printable ASCII (0x20..0x7e) passes through unchanged.
 * - Every other byte becomes '\xhh' with lowercase hex digits.
 *
 * @param {Uint8Array} u8
 * @returns {string}
 */
export function bytesToPythonRepr(u8) {
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < u8.length; i++) {
    const c = u8[i];
    if (c === 0x27) hasSingle = true; // '\''
    else if (c === 0x22) hasDouble = true; // '"'
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  const parts = ['b', quoteChar];
  for (let i = 0; i < u8.length; i++) {
    const c = u8[i];
    if (c === quote || c === 0x5c) {
      parts.push('\\', String.fromCharCode(c));
    } else if (c === 0x09) {
      parts.push('\\t');
    } else if (c === 0x0a) {
      parts.push('\\n');
    } else if (c === 0x0d) {
      parts.push('\\r');
    } else if (c >= 0x20 && c < 0x7f) {
      parts.push(String.fromCharCode(c));
    } else {
      parts.push('\\x', HEX[c >> 4], HEX[c & 0x0f]);
    }
  }
  parts.push(quoteChar);
  return parts.join('');
}

const HEX = '0123456789abcdef';

