node --input-type=module -e "
import { encodeUtf8, bytesToPythonRepr } from '/output/lib/pybytes.mjs';

let fails = 0;
const eq = (got, want, label) => {
  if (got !== want) { fails++; console.log('FAIL', label, JSON.stringify(got), '!==', JSON.stringify(want)); }
  else console.log('ok  ', label);
};

// Full byte range 0x00..0xff — verify against the CPython algorithm spec manually
// spot checks:
eq(bytesToPythonRepr(new Uint8Array([])), \"b''\", 'empty');
eq(bytesToPythonRepr(new Uint8Array([0x09,0x0a,0x0d])), \"b'\\\\t\\\\n\\\\r'\", 'tab/nl/cr');
eq(bytesToPythonRepr(new Uint8Array([0x5c])), \"b'\\\\\\\\'\", 'backslash');
eq(bytesToPythonRepr(new Uint8Array([0x27])), 'b\"\\'\"', 'single quote only -> double quotes');
eq(bytesToPythonRepr(new Uint8Array([0x22])), \"b'\\\"'\", 'double quote only -> single quotes');
eq(bytesToPythonRepr(new Uint8Array([0x27,0x22])), \"b'\\\\'\\\"'\", 'both quotes -> single quotes, escape single');
eq(bytesToPythonRepr(new Uint8Array([0x41,0x20,0x7e])), \"b'A ~'\", 'printable passthrough');
eq(bytesToPythonRepr(new Uint8Array([0x7f])), \"b'\\\\x7f'\", 'DEL escaped');
eq(bytesToPythonRepr(new Uint8Array([0x00,0x1f,0x80,0xff])), \"b'\\\\x00\\\\x1f\\\\x80\\\\xff'\", 'non-printable lowercase hex');

// sample ciphertext from the task
const hex = 'b79c38402fabc638cf040adecd3ce8109'.replace(/9$/,'0'); // hex string has odd length; interpret trailing 9 as 90? no —
" 2>&1 | head -30

