node --input-type=module -e "
import { bytesToPythonRepr, encodeUtf8 } from '/output/lib/pybytes.mjs';

const hex = 'b79c38402fabc638cf040adecd3ce8109';
console.log('hex length:', hex.length);
const u8 = new Uint8Array(hex.match(/../g).map(h => parseInt(h, 16)));
console.log('bytes:', u8.length);
console.log('repr:', bytesToPythonRepr(u8));

// expected hand-computed CPython repr for those bytes:
// b7->\\xb7 9c->\\x9c 38->'8' 40->'@' 2f->'/' ab->\\xab c6->\\xc6 38->'8'
// cf->\\xcf 04->\\x04 0a->\\n de->\\xde cd->\\xcd 3c->'<' e8->\\xe8 10->\\x10 9? last nibble issue

// encodeUtf8 checks
console.log('key utf8:', Array.from(encodeUtf8('yPcJ.h9oOX7e5!cV')).join(','));
console.log('data utf8:', Array.from(encodeUtf8('=b=M1F[g)],C0CZ6')).join(','));
console.log('utf8 multibyte:', Array.from(encodeUtf8('é€😀')).map(b=>b.toString(16)).join(' '));

// exhaustive round-trip vs node-internal knowledge: build expected for every byte value in isolation
let bad = 0;
for (let b = 0; b < 256; b++) {
  const r = bytesToPythonRepr(new Uint8Array([b]));
  let inner;
  if (b === 0x27) inner = \"'\", q='\"'; 
  let expected;
  if (b === 0x27) expected = 'b\"\\'\"';
  else if (b === 0x5c) expected = \"b'\\\\\\\\'\";
  else if (b === 9) expected = \"b'\\\\t'\";
  else if (b === 10) expected = \"b'\\\\n'\";
  else if (b === 13) expected = \"b'\\\\r'\";
  else if (b >= 0x20 && b < 0x7f) expected = \"b'\" + String.fromCharCode(b) + \"'\";
  else expected = \"b'\\\\x\" + b.toString(16).padStart(2,'0') + \"'\";
  if (r !== expected) { bad++; console.log('MISMATCH byte', b, JSON.stringify(r), JSON.stringify(expected)); }
}
console.log(bad === 0 ? 'all 256 single-byte reprs correct' : bad + ' mismatches');
"

