args.content:
// aes-ecb.mjs
//
// ECB (Electronic Codebook) mode wrapper around the raw AES block cipher in
// aes-core.mjs. Mirrors the pyaes API: the instance is constructed with the
// key once, then encrypt()/decrypt() may be called repeatedly on data whose
// length is a multiple of the 16-byte block size. No padding is applied.

import { BLOCK_SIZE, expandKey, encryptBlock, decryptBlock } from './aes-core.mjs';

export class AESModeOfOperationECB {
  // key must be a Uint8Array of 16 (AES-128), 24 (AES-192) or 32 (AES-256)
  // bytes. Throws RangeError on an invalid key length.
  constructor(key) {
    if (!(key instanceof Uint8Array)) {
      throw new TypeError('key must be a Uint8Array');
    }
    // expandKey performs the 16/24/32 length validation (RangeError).
    this._schedule = expandKey(key);
    this._keyLength = key.length;
  }

  // Encrypt data (Uint8Array, length a multiple of 16) under ECB mode.
  // Returns a new Uint8Array of the same length.
  encrypt(data) {
    this._checkData(data);
    const out = new Uint8Array(data.length);
    for (let offset = 0; offset < data.length; offset += BLOCK_SIZE) {
      out.set(
        encryptBlock(data.subarray(offset, offset + BLOCK_SIZE), this._schedule),
        offset
      );
    }
    return out;
  }

  // Decrypt data (Uint8Array, length a multiple of 16) under ECB mode.
  // Returns a new Uint8Array of the same length.
  decrypt(data) {
    this._checkData(data);
    const out = new Uint8Array(data.length);
    for (let offset = 0; offset < data.length; offset += BLOCK_SIZE) {
      out.set(
        decryptBlock(data.subarray(offset, offset + BLOCK_SIZE), this._schedule),
        offset
      );
    }
    return out;
  }

  _checkData(data) {
    if (!(data instanceof Uint8Array)) {
      throw new TypeError('data must be a Uint8Array');
    }
    if (data.length % BLOCK_SIZE !== 0) {
      throw new RangeError(
        `data length must be a multiple of ${BLOCK_SIZE} bytes, got ${data.length}`
      );
    }
  }
}

